using Microsoft.AspNetCore.Builder; using Microsoft.AspNetCore.Routing;
using JTradeERP.Application.Features.Security.Login; using JTradeERP.Application.Features.Security.RefreshAccessToken; using JTradeERP.Application.Features.Security.Logout; using JTradeERP.Application.Features.Security.GetMe;
using JTradeERP.Application.Features.Security.ForgotPassword; using JTradeERP.Application.Features.Security.ResetPassword;
using JTradeERP.Application.Features.Security.Administration.CreateUser; using JTradeERP.Application.Features.Security.Administration.UpdateUserStatus; using JTradeERP.Application.Features.Security.Administration.AssignRoles; using JTradeERP.Application.Features.Security.Administration.GetUserById; using JTradeERP.Application.Features.Security.Administration.GetUsers; using JTradeERP.Application.Features.Security.Administration.CreateRole; using JTradeERP.Application.Features.Security.Administration.UpdateRole; using JTradeERP.Application.Features.Security.Administration.GetRoleById; using JTradeERP.Application.Features.Security.Administration.GetRoles; using JTradeERP.Application.Features.Security.Administration.AssignPermissions; using JTradeERP.Application.Features.Security.Administration.GetPermissions;
using JTradeERP.Application.Features.Security.Administration.GetAuditLogs;
namespace JTradeERP.Application.Features.Security;
public static class SecurityEndpointExtensions
{ public static IEndpointRouteBuilder MapSecurityEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/auth");LoginEndpoint.Map(g);RefreshAccessTokenEndpoint.Map(g);LogoutEndpoint.Map(g);GetMeEndpoint.Map(g);ForgotPasswordEndpoint.Map(g);ResetPasswordEndpoint.Map(g);var a=e.MapGroup("/api/admin");CreateUserEndpoint.Map(a);GetUserByIdEndpoint.Map(a);GetUsersEndpoint.Map(a);UpdateUserStatusEndpoint.Map(a);AssignRolesEndpoint.Map(a);CreateRoleEndpoint.Map(a);UpdateRoleEndpoint.Map(a);GetRoleByIdEndpoint.Map(a);GetRolesEndpoint.Map(a);AssignPermissionsEndpoint.Map(a);GetPermissionsEndpoint.Map(a);GetAuditLogsEndPoint.Map(a);return e;} }
